# Task 8 — GameCoins rewritten with x and y
import numpy as np

def game_coins_xy(x, y):
    # [[1-y, x], [y, 1-x]] : columns still sum to 1
    return np.array([[1-y, x],
                     [y,   1-x]])

for x, y in ((0.3, 0.4), (0.0, 0.0), (1.0, 1.0)):
    G = game_coins_xy(x, y)
    print(f"x={x}, y={y} ->\n{G}   column sums {G.sum(axis=0)}")

# Tensor product of two probabilistic states.
#
# Rule 1 says the product distributes over addition; Rule 2 says the
# coefficients simply multiply. So the composite state is every pairing of a
# first-system outcome with a second-system outcome, weighted by the product of
# their probabilities.
first = {"0": 0.3, "1": 0.7}
second = {"0": 0.6, "1": 0.4}

composite = {}
for a, pa in first.items():
    for b, pb in second.items():
        composite[a + b] = pa * pb

for state, p in sorted(composite.items()):
    print(f"|{state}>  {p:.2f}")
print(f"total: {sum(composite.values()):.2f}")
print("A product state: knowing the first outcome tells you nothing about the second.")

