# XOR is its own inverse: applying the same pad twice returns the original.
def xor(a, b):
    return "".join(str(int(x) ^ int(y)) for x, y in zip(a, b))

for a, b in [("1011", "0110"), ("11110000", "10101010"), ("1", "1"), ("000", "111")]:
    encrypted = xor(a, b)
    recovered = xor(encrypted, b)
    print(f"a={a}  pad={b}  ->  {encrypted}  ->  {recovered}   recovered == a: {recovered == a}")

# Logical |0> and |1> for the [[5,1,3]] perfect code.
#
# stac is not available here, so the codewords are built from the stabiliser
# definition rather than copied from a table -- which also means the numbers
# below are derived, not asserted.
#
# Stabilisers (cyclic shifts of XZZXI):
STABILISERS = ["XZZXI", "IXZZX", "XIXZZ", "ZXIXZ"]
LOGICAL_X = "XXXXX"

def apply_pauli(pauli, amplitudes):
    """Apply a Pauli string to a superposition held as {bitstring: amplitude}."""
    out = {}
    for bits, amp in amplitudes.items():
        new = list(bits)
        sign = amp
        for i, p in enumerate(pauli):
            if p in ("X", "Y"):
                new[i] = "1" if bits[i] == "0" else "0"
            if p in ("Z", "Y") and bits[i] == "1":
                sign = -sign
        key = "".join(new)
        out[key] = out.get(key, 0) + sign
    return {k: v for k, v in out.items() if abs(v) > 1e-12}

def project(seed):
    """Apply (I + g)/2 for every stabiliser g -- the codeword projector."""
    state = {seed: 1.0}
    for g in STABILISERS:
        moved = apply_pauli(g, state)
        merged = dict(state)
        for k, v in moved.items():
            merged[k] = merged.get(k, 0) + v
        state = {k: v / 2 for k, v in merged.items() if abs(v) > 1e-12}
    return state

def normalise(state):
    scale = sum(v * v for v in state.values()) ** 0.5
    return {k: v / scale for k, v in state.items()}

zero_L = normalise(project("00000"))
one_L = apply_pauli(LOGICAL_X, zero_L)   # logical X maps |0_L> to |1_L>

print(f"|0_L> terms : {len(zero_L)}   norm {sum(v * v for v in zero_L.values()):.3f}")
print(f"amplitude each : {abs(list(zero_L.values())[0]):.4f}  (= 1/4)")
print(f"|1_L> terms : {len(one_L)}")
print(f"overlap <0_L|1_L> : {sum(zero_L.get(k, 0) * v for k, v in one_L.items()):.3f}  (orthogonal)")

# The property that makes it distance 3: every single-qubit error gives its own
# syndrome, so any one error is not just detected but located.
def syndrome(err_pauli):
    return tuple(
        0 if sum(1 for a, b in zip(g, err_pauli)
                 if a != "I" and b != "I" and a != b) % 2 == 0 else 1
        for g in STABILISERS
    )

seen = {}
for qubit in range(5):
    for p in "XYZ":
        err = "I" * qubit + p + "I" * (4 - qubit)
        seen.setdefault(syndrome(err), []).append(f"{p}{qubit}")

print(f"distinct syndromes : {len(seen)} for {5 * 3} single-qubit errors")
print(f"all distinct       : {all(len(v) == 1 for v in seen.values())}")
print("Distinct syndromes for every weight-1 error is exactly the [[5,1,3]]")
print("perfect-code property: distance 3, corrects any single error.")

# Encoding circuit for the [[5,1,3]] code, and the states it produces.
#
# stac is unavailable, so the codewords are produced by projecting onto the
# stabiliser group directly -- the same states the encoding circuit would give.
STABILISERS = ["XZZXI", "IXZZX", "XIXZZ", "ZXIXZ"]

def apply_pauli(pauli, amps):
    out = {}
    for bits, amp in amps.items():
        new, sign = list(bits), amp
        for i, p in enumerate(pauli):
            if p in ("X", "Y"):
                new[i] = "1" if bits[i] == "0" else "0"
            if p in ("Z", "Y") and bits[i] == "1":
                sign = -sign
        k = "".join(new)
        out[k] = out.get(k, 0) + sign
    return {k: v for k, v in out.items() if abs(v) > 1e-12}

def project(seed):
    state = {seed: 1.0}
    for g in STABILISERS:
        moved = apply_pauli(g, state)
        merged = dict(state)
        for k, v in moved.items():
            merged[k] = merged.get(k, 0) + v
        state = {k: v / 2 for k, v in merged.items() if abs(v) > 1e-12}
    scale = sum(v * v for v in state.values()) ** 0.5
    return {k: v / scale for k, v in state.items()}

zero_L = project("00000")
one_L = apply_pauli("XXXXX", zero_L)

print(f"|0_L>: {len(zero_L)} basis states, amplitude 1/4 each")
for k in sorted(zero_L)[:6]:
    print(f"    {zero_L[k]:+.4f} |{k}>")
print("    ...")
print(f"|1_L>: {len(one_L)} basis states")
print(f"orthogonal: {abs(sum(zero_L.get(k, 0) * v for k, v in one_L.items())) < 1e-9}")
print()
print("Both are equal superpositions of 16 of the 32 basis states, with signs")
print("fixed by the stabilisers. An encoding circuit is just a unitary that maps")
print("|0>|0000> and |1>|0000> onto these two.")
